sys_variable_value.value:
(function execute(inputs, outputs) {
    var rewardCount = 0;
    var totalAmount = 0;

     var gr = new GlideRecord('x_rwd_reward_history');

    gr.addQuery('employee', inputs.employee);
    gr.addQuery('quarter', inputs.quarter);
    gr.query();

    while (gr.next()) {

        var amou = parseFloat(gr.getValue('amount')) || 0;

        // Count only monetary rewards
        if (amou > 0) {
            rewardCount++;
            totalAmount += amou;
        }
    }

    outputs.reward_count = rewardCount;
    outputs.total_reward_amount = totalAmount;

})(inputs, outputs);

